import type {PlanTilemapSpec,PlanTilemapOptions,PlanTileShape,PlanColorAxisSpec} from '../../../src/plan.js';
export const tilemapExampleIds=['hexagon','circle','diamond','square','classes','explicit-domain','missing','sparse'] as const;
export type TilemapExampleId=typeof tilemapExampleIds[number];
export function tilemapExample(id:TilemapExampleId,locale:'es'|'en'):{spec:PlanTilemapSpec;options:PlanTilemapOptions;note:string}{
  const es=locale==='es',shape:PlanTileShape=id==='circle'||id==='diamond'||id==='square'?id:'hexagon';
  const data=Array.from({length:42},(_,i)=>({id:'cell-'+i,x:i%7-3,y:Math.floor(i/7)-2,value:id==='missing'&&i%4===0?null:(i*13)%81-20,name:(es?'Celda ':'Cell ')+(i+1)})).filter((_,i)=>id!=='sparse'||i%3!==1);
  const axis:PlanColorAxisSpec=id==='classes'?{kind:'classes',missingColor:'#CBD5E1',unclassifiedColor:'#94A3B8',classes:[{id:'cold',label:es?'Baja':'Low',maxExclusive:10,color:'#2563EB'},{id:'mild',label:es?'Media':'Medium',minInclusive:10,maxExclusive:30,color:'#8B5CF6'},{id:'warm',label:es?'Alta':'High',minInclusive:30,color:'#EF4444'}]}:{kind:'continuous',...(id==='explicit-domain'?{domain:[-10,40] as const}:{}),stops:[{at:0,color:'#DBEAFE'},{at:.5,color:'#3B82F6'},{at:1,color:'#1E3A8A'}],missingColor:'#CBD5E1'};
  const notes:Record<TilemapExampleId,string>={hexagon:es?'Hexágonos reales con columnas alternas y una escala de color común.':'Real hexagons use alternating columns and a common color scale.',circle:es?'Cada celda es un círculo con su propio color y valor original.':'Each cell is a circle with its own color and original value.',diamond:es?'Los rombos conservan su forma al cambiar el ancho disponible.':'Diamonds preserve their shape when available width changes.',square:es?'La cuadrícula usa posiciones enteras sin desplazar columnas alternas.':'The grid uses integer positions without alternating-column offsets.',classes:es?'Los límites incluyen el mínimo y excluyen el máximo de cada clase.':'Each class includes its minimum and excludes its maximum.', 'explicit-domain':es?'Los valores fuera del dominio conservan su número y sólo limitan su color.':'Values outside the domain keep their number; only the color is clamped.',missing:es?'Las celdas desconocidas conservan su color de ausencia y no se convierten en cero.':'Unknown cells keep their missing color and do not become zero.',sparse:es?'Los huecos respetan las posiciones originales; la paridad depende de la columna real.':'Gaps retain original positions; parity follows the actual source column.'};
  return{spec:{family:'tilemap',title:es?'Un mosaico de valores':'A grid of values',description:es?'Toca una celda conocida para consultar su valor.':'Touch a known cell to inspect its value.',unit:es?'unidades':'units',series:[{id:'measurements',name:es?'Medidas':'Measurements',data}],tileShape:shape,pointPadding:id==='square'?1.5:1,opacity:1,colorAxis:axis},options:{width:390,height:320},note:notes[id]};
}
